def should_stop(state):
    # 硬预算：轮数和累计 token 双重上限
    if state.turns >= MAX_TURNS or state.total_tokens >= TOKEN_BUDGET:
        return True, "budget_exhausted"
    # 语义终止信号
    if "TERMINATE" in state.last_message:
        return True, "explicit_terminate"
    # 无新增信息检测：与历史摘要的相似度过高则记一次无效轮
    if similarity(state.last_message, state.history_digest) > NO_NEW_INFO_THRESHOLD:
        state.stale_rounds += 1
    else:
        state.stale_rounds = 0
    if state.stale_rounds >= MAX_STALE_ROUNDS:
        return True, "no_new_information"
    return False, None
